{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A weary mapmaker unrolls a map of the ruined royal city.",
      "visual_description": "Mara spreads a torn parchment across a stone table at dusk, brass compass spinning beside a single candle, broken spires silhouetted in the window.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "An old lamp wakes and warns of traps ahead.",
      "visual_description": "The oracle lamp's single fiery eye flares to life on the table, casting long shadows over Mara's ink-stained sleeves.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork fox is wound up for the journey.",
      "visual_description": "Mara turns a tiny brass key on the tin fox's tail; its blue glass eyes blink open, gears ticking softly.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet steps out of a tall warped windowpane as if surfacing from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the looming castle gates.",
      "visual_description": "Massive iron gates hang half-open under torn royal banners; Mara, the glass diver, and the tin fox crouch behind a broken fountain.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "An official dozes at the toll booth, useless to anyone.",
      "visual_description": "The sleeping tax collector slumps in a cobwebbed booth, ledger as pillow, stamped papers fluttering from his sleeves as the team tiptoes past.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp warns away from a cursed tower.",
      "visual_description": "A leaning black tower glows with green runes; the oracle lamp's flame leans backward, eye narrowed, as Mara hesitates at a fork in the road.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "The clockwork fox darts between fallen statues, blue glass eyes scanning, its key-wind tail clicking as it pauses by a scorched royal banner.guards",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Frightened faces watch from shuttered windows.",
      "visual_description": "Pale eyes peek through cracked shutters along a narrow lane as Mara and the glass diver pass, the diver's coat reflecting their lantern light.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march through the smoky plaza.",
      "visual_description": "Rows of helmeted figures clank past a broken fountain; the team hides flat against a wall, the tin fox frozen mid-step, lamp dimmed to a whisper.",
      "characters": ["mara_the_cartographguesser", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Rumors of a great winged beast rattle the rooftops.",
      "visual_description": "A vast shadow sweeps across moonlit tiles; Mara grips her compass while the oracle lamp's eye widens, flame trembling.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver slips through a mirrored door.",
      "visual_description": "A tall silver mirror set into a stone wall ripples like water; the diver plunges in headfirst, coat trailing fractured reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, the diver finds the captive in a glass cell.",
      "visual_description": "A crystalline cell glows in a vaulted hall; the glass diver presses a gloved hand to the surface, helmet fogged with breath.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door demands a password from the lamp.",
      "visual_description": "Glowing sigils swirl across an iron door; the oracle lamp hovers close, its flame-eye spelling out words in golden sparks while Mara listens.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox trips an alarm bell on purpose.",
      "visual_description": "The clockwork fox yanks a frayed rope; an enormous cracked bell tilts and rings as the fox sprints down an alley, tail spinning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping official is shaken awake and immediately dozes again.",
      "visual_description": "Mara grips the tax collector's shoulders mid-corridor; his eyes flutter open, ledger slipping, then snap shut as he snores upright.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The team races toward the long bridge out of the city.",
      "visual_description": "A narrow stone bridge arches over a black chasm; Mara, the glass diver, the tin fox, and the oracle lamp run together as torchlight flares behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They cross safely as the ruined city fades behind.",
      "visual_description": "On the far side of the bridge, dawn breaks pink over distant hills; the group looks back at the smoking spires, the oracle lamp's eye finally calm.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

